    solve()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(N):
            if N <= 0:
                return 0
            s = str(N)
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dfs(pos, tight, started, counts):
                # counts is a tuple of 10 ints (c0..c9)
                if pos == n:
                    if not started:
                        return 0
                    if counts[0] > 0:
                        return 1
                    total = 0
                    prod = 1
                    for i in range(1, 10):
                        cnt = counts[i]
                        total += i * cnt
                        prod *= i ** cnt
                    if total == 0:
                        return 0
                    return 1 if prod % total == 0 else 0
                limit = int(s[pos]) if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    ntight = tight and (d == limit)
                    nstarted = started or (d != 0)
                    if not nstarted:
                        res += dfs(pos + 1, ntight, False, (0,)*10)
                    else:
                        lst = list(counts) if started else [0]*10
                        lst[d] += 1
                        res += dfs(pos + 1, ntight, True, tuple(lst))
                return res

            return dfs(0, True, False, (0,)*10)

        return count_upto(r) - count_upto(l - 1)

import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    # Compute prefix distinct counts
    pref = [0] * N
    seen = [False] * (N + 1)
    cnt = 0
    for i in range(N):
        if not seen[A[i]]:
            seen[A[i]] = True
            cnt += 1
        pref[i] = cnt

    # Compute suffix distinct counts
    suf = [0] * (N + 1)
    seen = [False] * (N + 1)
    cnt = 0
    for i in range(N - 1, -1, -1):
        if not seen[A[i]]:
            seen[A[i]] = True
            cnt += 1
        suf[i] = cnt
    suf[N] = 0

    # Segment tree with lazy propagation for range add and range max
    class SegTree:
        __slots__ = ('n', 'size', 'tree', 'lazy')
        def __init__(self, n):
            self.n = n
            self.size = 1
            while self.size < n:
                self.size <<= 1
            self.tree = [0] * (2 * self.size)
            self.lazy = [0] * (2 * self.size)

        def build(self, data):
            for i in range(self.n):
                self.tree[self.size + i] = data[i]
            for i in range(self.size - 1, 0, -1):
                self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

        def _apply(self, idx, val):
            self.tree[idx] += val
            self.lazy[idx] += val

        def _push(self, idx):
            if self.lazy[idx] != 0:
                self._apply(2*idx, self.lazy[idx])
                self._apply(2*idx+1, self.lazy[idx])
                self.lazy[idx] = 0

        def _add(self, idx, l, r, ql, qr, val):
            if ql > r or qr < l:
                return
            if ql <= l and r <= qr:
                self._apply(idx, val)
                return
            self._push(idx)
            mid = (l + r) // 2
            self._add(2*idx, l, mid, ql, qr, val)
            self._add(2*idx+1, mid+1, r, ql, qr, val)
            self.tree[idx] = max(self.tree[2*idx], self.tree[2*idx+1])

        def add(self, l, r, val):
            if l > r:
                return
            self._add(1, 0, self.size - 1, l, r, val)

        def _query(self, idx, l, r, ql, qr):
            if ql > r or qr < l:
                return -10**9
            if ql <= l and r <= qr:
                return self.tree[idx]
            self._push(idx)
            mid = (l + r) // 2
            left = self._query(2*idx, l, mid, ql, qr)
            right = self._query(2*idx+1, mid+1, r, ql, qr)
            return max(left, right)

        def query(self, l, r):
            if l > r:
                return -10**9
            return self._query(1, 0, self.size - 1, l, r)

    seg = SegTree(N)
    seg.build(pref)

    last_occ = [-1] * (N + 1)
    ans = 0

    for m in range(1, N - 1):
        val = A[m]
        prev = last_occ[val]
        l = max(prev, 0)
        r = m - 1
        if l <= r:
            seg.add(l, r, 1)
        max_val = seg.query(0, m - 1)
        candidate = max_val + suf[m + 1]
        if candidate > ans:
            ans = candidate
        last_occ[val] = m

    print(ans)

if __name__ == "__main__":
    solve()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # For each position j in the result word, collect constraints
        # Each constraint: (i, offset, char) where i is the index in str1,
        # offset is the index in str2 (j - i), and char is str2[offset]
        # T constraints require word[j] == char
        # F constraints require word[j] != char unless a prefix mismatch exists
        constraints = [[] for _ in range(L)]
        for i in range(n):
            for offset in range(m):
                j = i + offset
                if j >= L:
                    break
                constraints[j].append((i, offset, str2[offset]))

        word = [''] * L

        for j in range(L):
            # Determine if there's a forced character from T constraints
            forced = None
            for i, off, ch in constraints[j]:
                if str1[i] == 'T':
                    if forced is None:
                        forced = ch
                    elif forced != ch:
                        return ""  # Conflicting T constraints

            # Try characters from 'a' to 'z'
            found = False
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if forced is not None and c != forced:
                    continue

                # Check if this candidate works
                valid = True
                for i, off, ch in constraints[j]:
                    if str1[i] == 'T':
                        if c != ch:
                            valid = False
                            break
                    else:  # F constraint
                        if c == ch:
                            # Check if there's already a mismatch in the prefix of this substring
                            prefix_mismatch = False
                            for k in range(i, j):
                                if word[k] != '' and word[k] != str2[k - i]:
                                    prefix_mismatch = True
                                    break
                            if not prefix_mismatch:
                                valid = False
                                break

                if valid:
                    word[j] = c
                    found = True
                    break

            if not found:
                return ""

        return ''.join(word)

