import bisect

def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    input = sys.stdin.readline

    N = int(input())
    W = list(map(int, input().split()))
    L = [0] * N
    R = [0] * N
    intervals = []
    for i in range(N):
        l, r = map(int, input().split())
        L[i] = l
        R[i] = r
        intervals.append((l, r, i))

    # Sort intervals by L, then by R
    intervals_by_L = sorted(intervals, key=lambda x: (x[0], x[1]))
    pos_in_L = [0] * N
    for idx, (l, r, i) in enumerate(intervals_by_L):
        pos_in_L[i] = idx

    # Sort intervals by R, then by L
    intervals_by_R = sorted(intervals, key=lambda x: (x[1], x[0]))
    pos_in_R = [0] * N
    for idx, (l, r, i) in enumerate(intervals_by_R):
        pos_in_R[i] = idx

    right_neighbor = [-1] * N
    left_neighbor = [-1] * N

    L_sorted_vals = [l for l, r, i in intervals_by_L]
    R_sorted_vals = [r for l, r, i in intervals_by_R]

    for i in range(N):
        idx = bisect.bisect_right(L_sorted_vals, R[i])
        if idx < N:
            right_neighbor[i] = intervals_by_L[idx][2]
        idx = bisect.bisect_left(R_sorted_vals, L[i]) - 1
        if idx >= 0:
            left_neighbor[i] = intervals_by_R[idx][2]

    adj = [[] for _ in range(N)]
    for i in range(N):
        if right_neighbor[i] != -1:
            j = right_neighbor[i]
            adj[i].append(j)
            adj[j].append(i)
        if left_neighbor[i] != -1:
            j = left_neighbor[i]
            adj[i].append(j)
            adj[j].append(i)

    parent = list(range(N))
    rank = [0] * N

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        x = find(x)
        y = find(y)
        if x == y:
            return
        if rank[x] < rank[y]:
            parent[x] = y
        elif rank[x] > rank[y]:
            parent[y] = x
        else:
            parent[y] = x
            rank[x] += 1

    for i in range(N):
        if right_neighbor[i] != -1:
            union(i, right_neighbor[i])
        if left_neighbor[i] != -1:
            union(i, left_neighbor[i])

    LOG = (N).bit_length()
    up = [[-1] * N for _ in range(LOG)]
    depth = [0] * N
    sum_to_root = [0] * N
    visited = [False] * N

    def dfs(u, p, d, s):
        visited[u] = True
        up[0][u] = p if p != -1 else u
        depth[u] = d
        sum_to_root[u] = s
        for v in adj[u]:
            if v != p:
                dfs(v, u, d+1, s + W[v])

    for i in range(N):
        if not visited[i]:
            dfs(i, -1, 0, W[i])

    for k in range(1, LOG):
        for v in range(N):
            up[k][v] = up[k-1][up[k-1][v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    def path_sum(u, v):
        w = lca(u, v)
        return sum_to_root[u] + sum_to_root[v] - 2 * sum_to_root[w] + W[w]

    Q = int(input())
    out = []
    for _ in range(Q):
        s, t = map(int, input().split())
        s -= 1
        t -= 1
        if find(s) != find(t):
            out.append("-1")
        else:
            out.append(str(path_sum(s, t)))
    print("\n".join(out))

if __name__ == "__main__":
    threading.Thread(target=main).start()

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def to_perimeter(p):
            x, y = p
            if y == 0:          # bottom side: from (0,0) to (side,0)
                return x
            elif x == side:     # right side: from (side,0) to (side,side)
                return side + y
            elif y == side:     # top side: from (side,side) to (0,side)
                return 2 * side + (side - x)
            else:               # left side: from (0,side) to (0,0)
                return 3 * side + (side - y)

        coords = sorted(to_perimeter(p) for p in points)
        C = 4 * side
        n = len(coords)

        # Precompute the extended coordinates: coords + [c + C for c in coords]
        ext = coords + [c + C for c in coords]

        def can_place(D):
            # Try each starting point
            for start in range(n):
                # Greedy: place k points starting at ext[start]
                positions = [ext[start]]
                idx = start
                for _ in range(1, k):
                    # Find the next point with coordinate >= positions[-1] + D
                    target = positions[-1] + D
                    # Binary search in ext for the first coordinate >= target
                    lo, hi = idx + 1, 2 * n
                    while lo < hi:
                        mid = (lo + hi) // 2
                        if ext[mid] >= target:
                            hi = mid
                        else:
                            lo = mid + 1
                    if lo == 2 * n:
                        # No more points available in the extended range
                        break
                    positions.append(ext[lo])
                    idx = lo
                if len(positions) == k:
                    # Check the circular distance from the last placed point back to the start
                    # The last point is positions[-1], the start is ext[start]
                    # Clockwise distance from last to start: ext[start] + C - positions[-1]
                    # This must be >= D
                    if ext[start] + C - positions[-1] >= D:
                        return True
            return False

        # Binary search on the answer
        lo, hi = 0, C
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_place(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        # Directions: 0: (1,1), 1: (1,-1), 2: (-1,-1), 3: (-1,1)
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # Precompute dp1[i][j][d]: length of segment starting at (i,j) with value 1 going in direction d
        # dp2[i][j][d]: length starting with value 2
        # dp0[i][j][d]: length starting with value 0
        # Sequence: 1 -> 2 -> 0 -> 2 -> 0 -> ...
        # If start with 2: 2 -> 0 -> 2 -> 0 -> ...
        # If start with 0: 0 -> 2 -> 0 -> 2 -> ...

        dp1 = [[[0]*4 for _ in range(m)] for _ in range(n)]
        dp2 = [[[0]*4 for _ in range(m)] for _ in range(n)]
        dp0 = [[[0]*4 for _ in range(m)] for _ in range(n)]

        # Process from bottom-right to top-left to ensure dependencies are computed
        for i in range(n-1, -1, -1):
            for j in range(m-1, -1, -1):
                for d in range(4):
                    di, dj = dirs[d]
                    ni, nj = i + di, j + dj

                    # dp1: start with 1, next should be 2
                    if grid[i][j] == 1:
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            dp1[i][j][d] = 1 + dp2[ni][nj][d]
                        else:
                            dp1[i][j][d] = 1

                    # dp2: start with 2, next should be 0
                    if grid[i][j] == 2:
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 0:
                            dp2[i][j][d] = 1 + dp0[ni][nj][d]
                        else:
                            dp2[i][j][d] = 1

                    # dp0: start with 0, next should be 2
                    if grid[i][j] == 0:
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            dp0[i][j][d] = 1 + dp2[ni][nj][d]
                        else:
                            dp0[i][j][d] = 1

        ans = 0

        # Try all starting cells with value 1
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                for d in range(4):
                    # Case 1: no turn, straight segment
                    length = dp1[i][j][d]
                    if length > ans:
                        ans = length

                    # Case 2: one clockwise turn
                    # Turn at each step along the straight path
                    di, dj = dirs[d]
                    # d2 is clockwise: 0->1, 1->2, 2->3, 3->0
                    d2 = (d + 1) % 4

                    # Iterate over possible turn points
                    # k is the number of steps taken in first direction (0-indexed)
                    # At step k, we are at (i + k*di, j + k*dj)
                    # The value at that point must match the sequence
                    # k=0: value 1, k=1: value 2, k=2: value 0, k=3: value 2, k=4: value 0, ...
                    # We need to continue from that point in direction d2
                    # The continuation length depends on the value at the turn point

                    # We can iterate up to dp1[i][j][d] steps
                    max_steps = dp1[i][j][d]
                    for k in range(max_steps):
                        ti = i + k * di
                        tj = j + k * dj
                        if not (0 <= ti < n and 0 <= tj < m):
                            break

                        # Determine the value at turn point
                        # k=0: 1, k=1: 2, k=2: 0, k=3: 2, k=4: 0, ...
                        if k == 0:
                            val = 1
                        elif k % 2 == 1:
                            val = 2
                        else:
                            val = 0

                        # Get continuation length in direction d2
                        if val == 1:
                            cont = dp1[ti][tj][d2]
                        elif val == 2:
                            cont = dp2[ti][tj][d2]
                        else:
                            cont = dp0[ti][tj][d2]

                        # Total length: (k+1) steps in first direction + (cont - 1) steps in second direction
                        # Because the turn point is counted in both legs
                        total = (k + 1) + (cont - 1)
                        if total > ans:
                            ans = total

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        # Split pattern p into A, B, C at the two '*'
        star1 = p.find('*')
        star2 = p.find('*', star1 + 1)
        A = p[:star1]
        B = p[star1+1:star2]
        C = p[star2+1:]
        lenA, lenB, lenC = len(A), len(B), len(C)

        # If pattern is "**", empty substring matches, length 0
        if lenA == 0 and lenB == 0 and lenC == 0:
            return 0

        # Z-algorithm
        def z_algorithm(s):
            n = len(s)
            z = [0] * n
            z[0] = n
            l = r = 0
            for i in range(1, n):
                if i < r:
                    z[i] = min(r - i, z[i - l])
                while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l, r = i, i + z[i]
            return z

        # Compute prefA[i]: longest prefix of A matching s starting at i
        if lenA > 0:
            concat = A + '$' + s
            z = z_algorithm(concat)
            prefA = [0] * n
            offset = lenA + 1
            for i in range(n):
                prefA[i] = min(z[offset + i], lenA)
        else:
            prefA = [0] * n  # empty prefix always matches (length 0)

        # Compute prefB[i]: longest prefix of B matching s starting at i
        if lenB > 0:
            concat = B + '$' + s
            z = z_algorithm(concat)
            prefB = [0] * n
            offset = lenB + 1
            for i in range(n):
                prefB[i] = min(z[offset + i], lenB)
        else:
            prefB = [0] * n

        # Compute sufC[i]: longest suffix of C matching s ending at i
        if lenC > 0:
            rev_s = s[::-1]
            rev_c = C[::-1]
            concat = rev_c + '$' + rev_s
            z = z_algorithm(concat)
            sufC = [0] * n
            offset = lenC + 1
            for i in range(n):
                rev_pos = n - 1 - i
                if offset + rev_pos < len(concat):
                    sufC[i] = min(z[offset + rev_pos], lenC)
                else:
                    sufC[i] = 0
        else:
            sufC = [0] * n

        # validB[i] = True if prefB[i] >= lenB (i.e., B fully matches starting at i)
        if lenB > 0:
            validB = [prefB[i] >= lenB for i in range(n)]
        else:
            validB = [True] * n  # empty B matches anywhere

        # earliestB[i] = smallest index k <= i such that validB[k] is True, or n if none
        earliestB = [n] * n
        min_so_far = n
        for i in range(n):
            if validB[i]:
                min_so_far = min(min_so_far, i)
            earliestB[i] = min_so_far

        # Find shortest matching substring
        ans = float('inf')
        j = 0  # end pointer

        for i in range(n):
            # Check if A matches starting at i
            if prefA[i] < lenA:
                continue

            # Minimum end index needed:
            # substring s[i..j] must contain A, B, C
            # i + lenA - 1 is end of A
            # then B (lenB) and C (lenC)
            if lenB > 0:
                min_j = i + lenA - 1 + lenB + lenC
            else:
                min_j = i + lenA - 1 + lenC

            if min_j >= n:
                # As i increases, min_j increases, so no later i can work either
                break

            if j < min_j:
                j = min_j

            # Find smallest j >= min_j such that sufC[j] == lenC and
            # there exists valid B in [i+lenA, j-lenC]
            while j < n:
                if sufC[j] < lenC:
                    j += 1
                    continue

                left = i + lenA
                right = j - lenC

                if lenB == 0:
                    # B is empty, just need C at end and A at start
                    if right >= left - 1:  # j-lenC >= i+lenA-1, i.e., A and C can meet/overlap? No, they can't overlap if B is empty but both can be empty.
                        # Actually if B is empty, we just need A then C, they can be adjacent or overlap if one is empty
                        # left is start of B (i+lenA), right is end of B (j-lenC)
                        # If B is empty, we need left > right (i.e., the "gap" is empty)
                        # left = i + lenA, right = j - lenC
                        # We need i+lenA <= j-lenC+1, i.e., j >= i+lenA+lenC-1
                        # Which is exactly min_j. So we just need j >= min_j and C matches.
                        if j >= min_j:
                            break
                        else:
                            j += 1
                    else:
                        j += 1
                else:
                    if right < left:
                        j += 1
                        continue
                    # Check if earliestB[right] is in [left, right]
                    if earliestB[right] <= right and earliestB[right] >= left:
                        break
                    j += 1

            if j < n and sufC[j] >= lenC:
                # Final validation
                if lenB == 0:
                    if j >= i + lenA + lenC - 1:
                        ans = min(ans, j - i + 1)
                else:
                    if j - lenC >= i + lenA:
                        k = earliestB[j - lenC]
                        if k >= i + lenA and k <= j - lenC:
                            ans = min(ans, j - i + 1)

        return ans if ans != float('inf') else -1

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def min_moves(need):
            # Suffix max to get non-increasing f
            f = [0] * n
            cur = 0
            for i in range(n - 1, -1, -1):
                if need[i] > cur:
                    cur = need[i]
                f[i] = cur
            if f[0] == 0:
                return 0

            # Try the walk ending at cell e. Use recurrence:
            # c_0 = 2*f[0] - 1 - [e==0]
            # c_i = 2*f[i] - c_{i-1} - [e==i]  for 0 < i < n-1
            # Boundary at n-1: f[n-1] = a_{n-2} + [e==n-1]
            #   where a_{n-2} = (c_{n-2} + d_{n-2}) / 2
            #   and d_{n-2} = 1 - [e <= n-2]
            # Cost = 1 + sum(c_i for i in 0..n-2)

            # Only try e at positions where f changes or e=0 or e=n-1
            candidates = {0, n-1}
            for i in range(n-1):
                if f[i] > f[i+1]:
                    candidates.add(i+1)

            best = None
            for e in candidates:
                c0 = 2*f[0] - 1 - (1 if e == 0 else 0)
                if c0 < 0:
                    continue
                c = [c0]
                ok = True
                for i in range(1, n-1):
                    ci = 2*f[i] - c[-1] - (1 if e == i else 0)
                    if ci < 0:
                        ok = False
                        break
                    c.append(ci)
                if not ok:
                    continue
                # Check boundary at n-1
                d_last = 1 - (1 if e <= n-2 else 0)  # = 1 if e==n-1, else 0
                num = c[-1] + d_last
                if num < 0 or num % 2 != 0:
                    continue
                a_last = num // 2
                if a_last + (1 if e == n-1 else 0) != f[n-1]:
                    continue
                total = 1 + sum(c)
                if best is None or total < best:
                    best = total
            return best if best is not None else float('inf')

        def check(T):
            if T == 0:
                return True
            need = [(T + points[i] - 1) // points[i] for i in range(n)]
            return min_moves(need) <= m

        lo, hi = 0, max(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

