import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            aik = A[i][k]
            for j in range(n):
                C[i][j] = (C[i][j] + aik * B[k][j]) % mod
    return C

def mat_pow(M, p, mod):
    n = len(M)
    # Identity
    R = [[0]*n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1
    base = [row[:] for row in M]
    while p > 0:
        if p & 1:
            R = mat_mul(R, base, mod)
        base = mat_mul(base, base, mod)
        p >>= 1
    return R

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(next(it)))
        A.append(row)

    # Count zeros
    K = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1

    # Build C: A with zeros replaced by 0 (so walks using zero edges contribute 0)
    # Actually, we need the matrix where non-zero entries are A[i][j] and zero entries are 0
    C = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] != 0:
                C[i][j] = A[i][j] % p

    # Compute C^p mod p
    Cp = mat_pow(C, p, p)

    # (-1)^K mod p
    sign = 1 if K % 2 == 0 else (p - 1)

    # Result is (-1)^K * C^p mod p
    res = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            res[i][j] = (sign * Cp[i][j]) % p

    # Output
    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(res[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out_lines))

solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Helper: compute minimum flips needed to ensure no run exceeds L
        def flips_needed(L: int) -> int:
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run_len = j - i
                # To split a run of length run_len into pieces of length <= L,
                # we need ceil(run_len / L) - 1 flips (cuts between pieces).
                # If run_len <= L, no flips needed.
                if run_len > L:
                    total += (run_len + L - 1) // L - 1
                i = j
            return total

        # Binary search for the smallest L such that flips_needed(L) <= numOps
        lo, hi = 1, n
        answer = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if flips_needed(mid) <= numOps:
                answer = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return answer

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)
    degree = [0] * (N + 1)
    for i in range(1, N + 1):
        degree[i] = len(adj[i])
    max_kept = 0
    for c in range(1, N + 1):
        leaves = []
        for b in adj[c]:
            leaf = degree[b] - 1
            if leaf >= 1:
                leaves.append(leaf)
        if not leaves:
            continue
        leaves.sort(reverse=True)
        for i, y in enumerate(leaves):
            x = i + 1
            total = 1 + x + x * y
            if total > max_kept:
                max_kept = total
    ans = N - max_kept
    print(ans)

if __name__ == "__main__":
    solve()

class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        ans = n  # cost to delete everything

        # Try all possible number of distinct letters k and target frequency f
        for k in range(1, 27):
            if k > n:
                break
            for f in range(1, n + 1):
                # Weight for each letter: |cnt[i] - f| - cnt[i]
                weights = [abs(c - f) - c for c in cnt]
                weights.sort()
                # Sum of k smallest weights
                curr = sum(weights[:k])
                total = n + curr
                if total < ans:
                    ans = total
        return ans

from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        # Map value -> index for values that are <= threshold.
        # Values > threshold are isolated.
        pos = {}
        for i, v in enumerate(nums):
            if v <= threshold:
                pos[v] = i

        uf = UnionFind(n)

        # For each v in 1..threshold, union it with all its multiples in the array.
        for v in range(1, threshold + 1):
            if v not in pos:
                continue
            base_idx = pos[v]
            # iterate multiples of v: 2v, 3v, ...
            multiple = 2 * v
            while multiple <= threshold:
                if multiple in pos:
                    uf.union(base_idx, pos[multiple])
                multiple += v

        # Count unique roots among all indices.
        roots = set()
        for i in range(n):
            roots.add(uf.find(i))
        return len(roots)
